PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('child','admin')), created_at INTEGER NOT NULL);
CREATE TABLE setup_lock (id INTEGER PRIMARY KEY CHECK(id=1), user_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE TABLE invites (token_hash TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('child','admin')), created_by TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, used_by TEXT REFERENCES users(id));
CREATE TABLE auth_limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE photos (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), mime TEXT NOT NULL, data BLOB NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE chores (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', photo_id TEXT NOT NULL REFERENCES photos(id), status TEXT NOT NULL CHECK(status IN ('pending','approved','redo')), quality TEXT CHECK(quality IN ('well','basic')), tip INTEGER CHECK(tip BETWEEN 0 AND 100000), reviewed_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE INDEX chores_user ON chores(user_id,created_at);
CREATE TABLE requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('cash','buy')), item TEXT NOT NULL DEFAULT '', amount INTEGER NOT NULL CHECK(amount > 0 AND amount <= 100000), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','cancelled','declined')), reviewed_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE INDEX requests_user ON requests(user_id,status);
CREATE TABLE ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('reward','demerit','spend')), amount INTEGER NOT NULL, tip INTEGER NOT NULL DEFAULT 0, name TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), source_id TEXT UNIQUE, created_at INTEGER NOT NULL);
CREATE INDEX ledger_user ON ledger(user_id,created_at);
CREATE TRIGGER chore_reward AFTER UPDATE OF status ON chores WHEN OLD.status='pending' AND NEW.status='approved' BEGIN INSERT INTO ledger(id,user_id,kind,amount,tip,name,actor_id,source_id,created_at) VALUES(NEW.id,NEW.user_id,'reward',50+NEW.tip,NEW.tip,NEW.name,NEW.reviewed_by,NEW.id,unixepoch()); END;
CREATE TRIGGER request_reserve BEFORE INSERT ON requests BEGIN SELECT (CASE WHEN NEW.amount > COALESCE((SELECT SUM(amount) FROM ledger WHERE user_id=NEW.user_id),0) - COALESCE((SELECT SUM(amount) FROM requests WHERE user_id=NEW.user_id AND status='pending'),0) THEN RAISE(ABORT,'insufficient_funds') END); END;
CREATE TRIGGER request_fulfill_guard BEFORE UPDATE OF status ON requests WHEN OLD.status='pending' AND NEW.status='completed' BEGIN SELECT (CASE WHEN COALESCE((SELECT SUM(amount) FROM ledger WHERE user_id=NEW.user_id),0) < COALESCE((SELECT SUM(amount) FROM requests WHERE user_id=NEW.user_id AND status='pending'),0) THEN RAISE(ABORT,'insufficient_funds') END); END;
CREATE TRIGGER request_spend AFTER UPDATE OF status ON requests WHEN OLD.status='pending' AND NEW.status='completed' BEGIN INSERT INTO ledger(id,user_id,kind,amount,name,actor_id,source_id,created_at) VALUES(NEW.id,NEW.user_id,'spend',-NEW.amount,CASE WHEN NEW.kind='cash' THEN 'Cash withdrawn' ELSE 'Purchased: '||NEW.item END,NEW.reviewed_by,NEW.id,unixepoch()); END;
CREATE TABLE signup_guard (id TEXT NOT NULL CHECK(id IS NULL));
